import {createCommunity} from './community.js';
import {journeys} from './journeys.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icon=n=>window.GH_ICONS[n]||window.GH_ICONS.repo;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types={skill:'增长方法',experience:'实战心得',tool:'开源工具'};
const topics=['GEO','SEO','AI 自动化','用户获取','内容增长','产品增长'];
const levels={beginner:'无需编程',manual:'需要配置工具',technical:'需要技术协助'};
const colors=['#365744','#5d6856','#716853','#526d66','#777156'];
const av=(name,size='')=>`<span class="avatar ${size}" style="--av:${colors[[...String(name)].reduce((a,c)=>a+c.charCodeAt(0),0)%colors.length]}">${esc(String(name).slice(0,2).toUpperCase())}</span>`;
const date=t=>new Date(t).toLocaleDateString('zh-CN',{month:'short',day:'numeric'});
const href=id=>'#repo/'+encodeURIComponent(id);
const authorKey=r=>r.sample?r.owner:r.ownerId;
let state={resources:[],stars:[],practices:[],user:null,route:'explore',q:'',type:'all',topic:'all',sort:'featured',level:'all',id:null,tab:'guide',detail:null,loading:false,error:null};
let lastListing='#explore',toastTimer,loadVersion=0,editor=null,editorStep='write';
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
async function api(path,method='GET',body){let res;try{res=await fetch('/api/'+path,{method,headers:body?{'content-type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})})}catch{throw Error('连接中断，输入已保留。请恢复网络后重试。')}let data;try{data=await res.json()}catch{throw Error('无法连接数据服务，请稍后重试')}if(!res.ok){if(res.status===401&&state.user&&!path.startsWith('auth/')){const next=location.hash;saveDraft();if($('#modal').open)closeModal();state.user=null;go('#login?error=expired&next='+encodeURIComponent(next))}throw Object.assign(new Error(data.error||'操作失败'),{status:res.status})}return data}
async function refresh(){const b=await api('bootstrap');Object.assign(state,{resources:b.resources,stars:b.stars,user:b.user,auth:b.auth,practices:b.practices||[]});}
const repo=id=>state.resources.find(r=>r.id===id);
const isOwn=r=>r?.ownerId===state.user?.id;
function markdown(input){let code=false,lines=[],out=[],list=false;const end=()=>{if(list){out.push('</ul>');list=false}};String(input).split('\n').forEach(raw=>{if(raw.startsWith('```')){end();if(code){out.push('<pre><code>'+esc(lines.join('\n'))+'</code></pre>');lines=[]}code=!code;return}if(code){lines.push(raw);return}let s=esc(raw).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');if(raw.startsWith('- ')){if(!list){out.push('<ul>');list=true}out.push('<li>'+s.slice(2)+'</li>');return}end();if(/^#{1,3} /.test(raw)){const n=raw.indexOf(' ');out.push(`<h${n}>${s.slice(n+1)}</h${n}>`)}else if(raw.startsWith('> '))out.push('<blockquote>'+s.slice(5)+'</blockquote>');else if(raw.trim())out.push('<p>'+s+'</p>')});end();if(code)out.push('<pre><code>'+esc(lines.join('\n'))+'</code></pre>');return out.join('')}
function shell(){const r=repo(state.id);$('#app').innerHTML=`<header class="global-header"><button class="icon-btn menu-toggle" data-action="menu" aria-label="打开导航" aria-expanded="false">${icon('three-bars')}</button><a href="#explore" class="brand" aria-label="GrowthHub 首页"><span class="brand-mark"><i></i><i></i><i></i></span><strong>GrowthHub</strong></a><span class="brand-caption">增长实践者的知识社区</span><label class="global-search">${icon('search')}<input id="search" aria-label="搜索增长资源" placeholder="搜索方法、工具或想解决的问题…" value="${esc(state.q)}" maxlength="100"><kbd>/</kbd></label><button class="btn primary header-new" data-action="publish" aria-label="发布资源">${icon('plus')}<span>发布资源</span></button>${state.user?`<button class="icon-btn header-inbox" data-action="inbox" aria-label="消息通知">${icon('comment-discussion')}</button><button class="avatar-button" data-action="account-menu" aria-label="账户菜单">${av(state.user.name)}</button>`:'<button class="btn header-signin" data-action="login">登录 / 注册</button>'}</header><nav class="global-nav" aria-label="主导航">${[['explore','globe','发现'],['trending','flame','实践榜'],['collections','bookmark','入门路线'],['practice','check-circle','我的实践'],['stars','star','我的收藏'],['profile','repo','我的资源']].map(([p,i,t])=>`<a href="#${p}" ${state.route===p?'aria-current="page"':''}>${icon(i)}${t}${p==='stars'?`<span class="counter">${state.stars.length}</span>`:''}</a>`).join('')}<span class="nav-status">${icon('shield-check')}邀请试用</span></nav><main id="main" tabindex="-1"></main><footer class="site-footer"><span class="footer-brand">${icon('repo')}GrowthHub</span><span>让知识被复用，让经验有来处。</span><button data-action="guide">使用指南</button><button data-action="about">关于与公约</button><a href="#terms">社区约定</a><a href="#privacy">隐私说明</a><span>© 2026</span></footer><nav class="mobile-nav" aria-label="手机导航">${[['explore','globe','发现'],['collections','bookmark','路线'],['publish','plus','发布'],['stars','star','收藏'],['profile','person','我的']].map(([p,i,t])=>p==='publish'?`<button data-action="publish">${icon(i)}${t}</button>`:`<a href="#${p}" ${state.route===p?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('')}</nav>`;renderMain()}
function go(hash){if($('#modal').open)closeModal();if(location.hash===hash)route();else location.hash=hash;document.body.classList.remove('nav-open')}
async function route(){const [path,query='']=(location.hash.slice(1)||'explore').split('?');const parts=path.split('/'),p=new URLSearchParams(query);state.route=['explore','trending','collections','stars','profile','repo','author','journey','practice','login','signup','recover','reset-password','verify','onboarding','settings','drafts','inbox','admin','terms','privacy'].includes(parts[0])?parts[0]:'explore';try{state.id=decodeURIComponent(parts[1]||'')}catch{state.id=''}state.q=p.get('q')||'';state.type=p.get('type')||(state.route==='explore'?'skill':'all');state.topic=p.get('topic')||'all';state.level=p.get('level')||'all';state.sort=p.get('sort')||(state.route==='trending'?'practiced':state.route==='explore'?'popular':'featured');if(['explore','trending'].includes(state.route)&&!['popular','practiced','updated'].includes(state.sort))state.sort='popular';state.tab=p.get('tab')||'guide';state.detail=null;state.error=null;if(state.route!=='repo')lastListing=location.hash||'#explore';shell();window.scrollTo(0,0);if(state.route==='repo')await loadDetail();}
async function loadDetail(){const token=++loadVersion;state.loading=true;renderMain();try{const d=await api('resources/'+encodeURIComponent(state.id));if(token!==loadVersion||state.route!=='repo')return;state.detail=d;state.loading=false;renderMain()}catch(e){if(token!==loadVersion)return;state.error=e.message;state.loading=false;renderMain()}}
function updateQuery(){const p=new URLSearchParams();for(const k of ['q','type','topic','level','sort'])if(state[k]&&state[k]!==({q:'',type:state.route==='explore'?'skill':'all',topic:'all',level:'all',sort:state.route==='explore'?'popular':state.route==='trending'?'practiced':'featured'}[k]))p.set(k,state[k]);history.replaceState(null,'','#'+state.route+(p.size?'?'+p:''));lastListing=location.hash;renderMain()}
function toggleTopic(topic) {
  if ($('#modal').open) closeModal();
  if (['explore','trending','stars','profile','author'].includes(state.route)) {
    state.topic = state.topic === topic ? 'all' : topic;
    updateQuery();
  } else {
    go('#explore?type=all&topic=' + encodeURIComponent(topic));
  }
}
function filtered(){let a=state.resources.filter(r=>!r.status||r.status==='published'||state.route==='profile'&&isOwn(r));if(state.route==='stars')a=a.filter(r=>state.stars.includes(r.id));if(state.route==='profile')a=a.filter(isOwn);if(state.route==='author')a=a.filter(r=>authorKey(r)===state.id);a=a.filter(r=>(state.type==='all'||r.type===state.type)&&(state.topic==='all'||r.topic===state.topic||r.tags.includes(state.topic))&&(state.level==='all'||r.difficulty===state.level)&&(!state.q||[r.title,r.desc,r.owner,r.name,...r.tags].join(' ').toLowerCase().includes(state.q.toLowerCase())));if(state.sort==='popular')a.sort((a,b)=>b.stars-a.stars||b.forks-a.forks||b.updatedAt-a.updatedAt||a.id.localeCompare(b.id));if(state.sort==='practiced')a.sort((a,b)=>(b.practiceCount||0)-(a.practiceCount||0)||b.updatedAt-a.updatedAt||a.id.localeCompare(b.id));if(state.sort==='updated')a.sort((a,b)=>b.updatedAt-a.updatedAt||a.id.localeCompare(b.id));return a}
function starButton(r){const on=state.stars.includes(r.id);return `<button class="btn btn-sm ${on?'starred':''}" data-star="${esc(r.id)}" aria-label="${on?'取消收藏':'收藏'} ${esc(r.title)}" aria-pressed="${on}">${icon(on?'star-fill':'star')}<span>${on?'已收藏':'收藏'}</span><span class="button-count">${r.stars||0}</span></button>`}
function tags(r){return `<div class="tags">${r.tags.map(t=>`<button data-topic="${esc(t)}" aria-pressed="${state.topic===t}">${esc(t)}</button>`).join('')}</div>`}
function coverFor(r){return r.topic==='GEO'||r.topic==='SEO'?'cover-discovery.jpg':r.type==='experience'||r.topic==='用户获取'?'cover-community.jpg':'cover-workflow.jpg'}
function resourceRow(r){return `<article class="resource-row"><a class="resource-cover" href="${href(r.id)}" tabindex="-1" aria-hidden="true"><img src="/${coverFor(r)}" alt="" loading="lazy" width="600" height="400"></a><div class="row-body"><div class="card-category"><span>${types[r.type]} · ${esc(r.topic)}</span><span class="sample-label">${r.sample?'示例':r.status==='archived'?'已下架':r.status==='hidden'?'审核隐藏':'社区资源'}</span></div><h3><a href="${href(r.id)}">${esc(r.title)}</a></h3><p class="resource-desc">${esc(r.desc)}</p>${tags(r)}<div class="resource-meta"><span>${icon('check-circle')}${levels[r.difficulty]||'无需编程'}</span>${r.practiceCount?`<span>${r.practiceCount} 份实践</span>`:''}${r.evidenceStatus&&r.evidenceStatus!=='untested'?`<span>作者自述 · ${outcomes[r.evidenceStatus]}</span>`:''}</div><div class="card-footer"><a class="card-author" href="#author/${encodeURIComponent(authorKey(r))}">${av(r.owner)}<span>${esc(r.owner)}</span></a>${starButton(r)}</div></div></article>`}
function featuredSpotlight(){const r=repo('geo-playbook');if(!r)return '';return `<div class="discovery-top"><a class="editorial-feature" href="${href(r.id)}"><div class="feature-copy"><span class="feature-label">入门手册 · GEO · 示例</span><h2>让你的品牌，<br>被 AI 看见。</h2><p>从可见度诊断，到第一轮内容实验。<br>一份可以跟着做的增长手册。</p><span class="feature-link">阅读手册 ${icon('chevron-right')}</span></div><img src="/cover-discovery.jpg" alt="" width="600" height="400" fetchpriority="high"></a>${goalPicker()}</div>`}
function filterBar(){return `<div class="filter-bar"><div class="segmented" aria-label="资源类型">${[['all','全部'],...Object.entries(types)].map(([v,t])=>`<button data-filter-type="${v}" aria-pressed="${state.type===v}">${t}</button>`).join('')}</div><div class="select-filters"><label><span class="sr-only">使用门槛</span><select id="level-filter"><option value="all">所有门槛</option>${Object.entries(levels).map(([k,v])=>`<option value="${k}" ${state.level===k?'selected':''}>${v}</option>`).join('')}</select></label><label><span class="sr-only">资源排序</span><select id="sort-filter">${[['featured','精选排序'],['practiced','最多实践记录'],['popular','最多收藏'],['updated','最近更新']].map(([k,v])=>`<option value="${k}" ${state.sort===k?'selected':''}>${v}</option>`).join('')}</select></label></div></div>`}
function empty(title,body,action='reset',button='浏览全部资源'){return `<div class="empty-state">${icon('repo')}<h2>${title}</h2><p>${body}</p><button class="btn" data-action="${action}">${button}</button></div>`}
function sidebar(){return `<aside class="explore-sidebar"><h2>探索增长</h2><p>找到下一步可以实践的方法。</p><nav aria-label="资源分类">${[['all','globe','全部资源'],['skill','book','增长方法'],['experience','comment-discussion','实战心得'],['tool','tools','开源工具']].map(([k,i,v])=>`<button data-filter-type="${k}" ${state.type===k?'class="active"':''}>${icon(i)}${v}<span>${state.resources.filter(r=>(!r.status||r.status==='published')&&(k==='all'||r.type===k)).length}</span></button>`).join('')}</nav><h3>按增长问题探索</h3><nav aria-label="增长话题">${topics.map(t=>`<button data-topic="${t}" aria-pressed="${state.topic===t}" ${state.topic===t?'class="active"':''}>${icon('hash')}${t}</button>`).join('')}</nav><div class="sidebar-help">${icon('light-bulb')}<strong>第一次来？</strong><p>不需要懂代码。先找一个问题，再保存一份方法去实践。</p><button data-action="guide">了解如何使用 ${icon('chevron-right')}</button></div></aside>`}
function rightRail(){return `<aside class="discovery-rail"><section><h3>${icon('bookmark')}从这里开始</h3><a href="#repo/geo-playbook" class="learning-card"><div class="learning-icon">${icon('globe')}</div><span class="overline">入门路线 · GEO</span><strong>让品牌被 AI 看见</strong><p>从可见度基线，到第一轮内容实验。</p><span class="learn-link">打开实战手册 ${icon('chevron-right')}</span></a></section><section><h3>${icon('people')}资源贡献者</h3>${[...new Set(state.resources.map(r=>r.owner))].slice(0,4).map(n=>`<a class="contributor" href="#author/${encodeURIComponent(n)}">${av(n)}<div><strong>${esc(n)}</strong><span>${state.resources.filter(r=>r.owner===n).length} 个资源</span></div>${icon('chevron-right')}</a>`).join('')}</section><section class="community-note"><h3>分享方法，也分享边界</h3><p>好的资源包括适用场景、具体步骤、观察结果和失败经验。</p><button class="btn" data-action="publish">${icon('plus')}贡献一个资源</button></section><p class="rail-note">标注“示例”的内容用于体验流程，收藏与复用数字只统计本站真实操作。</p></aside>`}
function syncShell(){const count=$('.global-nav a[href="#stars"] .counter');if(count)count.textContent=state.stars.length;$$('.global-nav>a,.mobile-nav>a').forEach(a=>{if(a.getAttribute('href')==='#'+state.route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const context=$('.header-context');if(context)context.textContent=state.route==='repo'?(repo(state.id)?.owner||'资源'):'探索';if(state.route!=='repo')document.title='GrowthHub · 让增长经验持续进化';}
function renderMain(){if(!$('#main'))return;syncShell();document.body.dataset.page=state.route;if(community.render())return;if(state.route==='repo'){renderRepo();return}if(state.route==='collections'){renderCollections();return}if(state.route==='journey'){renderJourney();return}if(state.route==='practice'){renderPractices();return}if(['explore','trending'].includes(state.route)){renderDiscovery();return}const list=filtered(),personal=state.route==='profile'||state.route==='author';const name=state.route==='author'?(state.resources.find(r=>authorKey(r)===state.id)?.owner||'社区成员'):state.user?.name;const title=state.route==='trending'?'社区实践趋势':state.route==='stars'?'我的收藏':personal?name:'发现下一种增长可能。';$('#main').innerHTML=`<div class="explore-layout">${sidebar()}<div class="explore-content"><div class="page-heading"><div>${personal?`<div class="profile-heading">${av(name,'large')}<div><h1>${esc(title)}</h1><p>${state.route==='profile'?esc(state.user?.bio||'写下实践，分享下一种可能。'):'增长方法与实践分享'}</p></div></div>`:`<h1>${title}</h1><p>${state.route==='stars'?'收藏的资源都在这里，随时回来继续实践。':state.route==='trending'?'按已分享的实践记录数排序。记录包含成功与失败，不代表效果保证。':'方法、心得与工具，让增长经验持续复用。'}</p>`}</div>${state.route==='profile'?'<a class="btn" href="#drafts">云端草稿</a><a class="btn" href="#settings">账户设置</a>':''}</div>${state.route==='explore'&&!state.q&&state.topic==='all'?`${featuredSpotlight()}`:''}<div class="content-columns"><section class="resource-feed"><div class="feed-title"><h2>${personal?'资源':state.route==='stars'?'已收藏':'探索资源'}<span class="counter">${list.length}</span></h2>${state.route==='profile'?'<button class="btn primary btn-sm" data-action="publish">新建资源</button>':'<span class="muted">找到方法，然后开始实践</span>'}</div>${filterBar()}${state.q||state.topic!=='all'||state.level!=='all'?`<div class="filter-summary"><span>${state.q?'“'+esc(state.q)+'” · ':''}${state.topic!=='all'?esc(state.topic)+' · ':''}${list.length} 个结果</span><button data-action="clear-filters">${icon('x')}清除筛选</button></div>`:''}<div class="resource-list">${list.length?list.map(resourceRow).join(''):empty(state.route==='stars'?'把好方法留在手边':personal?'从你的第一个资源开始':'没有找到匹配资源',state.q||state.type!=='all'||state.topic!=='all'||state.level!=='all'?'试试其他关键词，或清除筛选条件。':'分享一个方法、一次复盘，或保存一份值得实践的资源。',personal?'publish':'reset',personal?'发布资源':'浏览全部资源')}</div><div class="list-end">${list.length?'已展示 '+list.length+' 个资源':''}</div></section></div>${state.route==='profile'?`<a class="practice-profile-link" href="#practice">${icon('check-circle')}我的实践 · ${state.practices.length} 项，继续记录结果 ${icon('chevron-right')}</a>`+legacyNotice():''}</div></div>`}
const rankingModes = {popular:'最多收藏',practiced:'最多实践',updated:'最近更新'};
function rankingRow(r, index) {
  const count = state.sort === 'practiced' ? r.practiceCount || 0 : r.stars || 0;
  return `<li class="ranking-row ${index < 3 ? 'rank-leading' : ''}">
    <span class="rank-position" aria-label="第 ${index + 1} 位">${String(index + 1).padStart(2,'0')}</span>
    <article class="ranking-body">
      <div class="ranking-byline"><a href="#author/${encodeURIComponent(authorKey(r))}">${av(r.owner)}${esc(r.owner)}</a><span class="ranking-type">${r.type === 'skill' ? 'Skill' : types[r.type]}</span>${r.sample ? '<span class="sample-label">示例</span>' : ''}</div>
      <h2><a href="${href(r.id)}">${esc(r.title)}</a></h2>
      <p class="ranking-description">${esc(r.desc)}</p>
      ${tags(r)}
      <div class="ranking-meta"><span>${icon('check-circle')}${levels[r.difficulty] || '无需编程'}</span><span>${icon('repo-forked')}${r.forks || 0} 次复用</span><span>${icon('graph')}${r.practiceCount || 0} 份实践</span><span class="ranking-updated">${date(r.updatedAt)}更新</span></div>
    </article>
    <div class="ranking-actions">${starButton(r)}<span class="ranking-signal">${state.sort === 'updated' ? `${icon('graph')}${date(r.updatedAt)}更新` : `${icon(state.sort === 'practiced' ? 'graph' : 'star')}<strong>${count}</strong>${state.sort === 'practiced' ? '份公开实践' : '次累计收藏'}`}</span><a class="ranking-read" href="${href(r.id)}">查看方法 ${icon('chevron-right')}</a></div>
  </li>`;
}
function discoveryAside() {
  return `<aside class="discovery-aside"><a class="discovery-start" href="#collections"><img src="/cover-discovery.jpg" alt="" width="600" height="400"><div><span>第一次实践</span><h2>从一个小问题开始。</h2><p>选一条三步路线，把读过的方法用起来。</p><strong>浏览入门路线 ${icon('chevron-right')}</strong></div></a>${goalPicker()}<div class="discovery-contribute"><h3>你的经验，值得被复用。</h3><p>分享具体步骤，也写下适用条件和踩过的坑。</p><button class="btn" data-action="publish">${icon('plus')}分享一个 Skill</button></div></aside>`;
}
function renderDiscovery() {
  const list = filtered();
  const hasFilter = state.q || state.topic !== 'all' || state.level !== 'all';
  const note = state.sort === 'popular' ? '按累计收藏排序；同分参考复用数和更新时间。' : state.sort === 'practiced' ? '按已分享的完整实践记录数排序，包含成功与失败。' : '按资源最近更新时间排序。';
  document.title = `${state.route === 'trending' ? '实践榜' : '发现增长 Skills'} · GrowthHub`;
  $('#main').innerHTML = `<div class="explore-layout discovery-layout">${sidebar()}<div class="explore-content"><header class="discovery-heading"><div><h1>${state.route === 'trending' ? '社区实践榜' : '发现增长 Skills'}</h1><p>${state.route === 'trending' ? '看看哪些方法，正在被大家付诸实践。' : '值得收藏的增长方法，从这里开始。'}</p></div><a href="#collections">不知道选什么？${icon('chevron-right')}</a></header><div class="discovery-columns"><section class="ranking-feed" aria-label="增长资源排行榜"><div class="ranking-toolbar"><div class="ranking-tabs" aria-label="排行榜排序">${Object.entries(rankingModes).map(([key,label])=>`<button data-sort="${key}" aria-pressed="${state.sort === key}">${icon(key === 'popular' ? 'star' : key === 'practiced' ? 'graph' : 'repo')}${label}</button>`).join('')}</div><span class="ranking-total">${list.length} 个资源</span></div><div class="ranking-filters"><label><span class="sr-only">资源类型</span><select id="discovery-type">${[['skill','增长 Skills'],['all','全部资源'],['experience','实战心得'],['tool','开源工具']].map(([key,label])=>`<option value="${key}" ${state.type===key?'selected':''}>${label}</option>`).join('')}</select></label><label><span class="sr-only">增长话题</span><select id="discovery-topic"><option value="all">全部话题</option>${state.topic!=='all'&&!topics.includes(state.topic)?`<option value="${esc(state.topic)}" selected>${esc(state.topic)}</option>`:''}${topics.map(t=>`<option value="${t}" ${state.topic===t?'selected':''}>${t}</option>`).join('')}</select></label><label><span class="sr-only">使用门槛</span><select id="level-filter"><option value="all">所有门槛</option>${Object.entries(levels).map(([key,label])=>`<option value="${key}" ${state.level===key?'selected':''}>${label}</option>`).join('')}</select></label><details class="ranking-help"><summary>${icon('info')}排序说明</summary><p>${note}数字只统计本站真实操作，收藏与实践数量不代表效果验证；示例已单独标注。</p></details></div>${hasFilter?`<div class="filter-summary"><span>${state.q?'“'+esc(state.q)+'” · ':''}${state.topic!=='all'?esc(state.topic)+' · ':''}${list.length} 个结果</span><button data-action="clear-filters">${icon('x')}清除筛选</button></div>`:''}${list.length ? `<ol class="ranking-list">${list.map(rankingRow).join('')}</ol>` : empty('没有找到匹配的资源','试试其他话题或使用门槛，或清除筛选条件。','clear-filters','清除筛选')}<p class="ranking-footnote">${note}<br>示例用于体验流程，收藏与实践数量不代表效果验证。</p></section>${discoveryAside()}</div></div></div>`;
}
function legacyNotice(){try{const old=JSON.parse(localStorage.getItem('growthhub-v1')||'{}');if(old.custom?.length)return `<div class="notice">${icon('info')}此浏览器还有 ${old.custom.length} 份旧版资源。<button data-action="export-legacy">下载备份</button>，原内容仍保留。</div>`}catch{}return ''}
function renderCollections(){$('#main').innerHTML=`<div class="collections-page"><div class="page-heading"><div><h1>从一个问题开始</h1><p>每条路线只有三步。选一件今天就能开始的事。</p></div><span class="badge">按步骤实践</span></div><div class="collection-grid">${journeys.map((j,i)=>`<a class="collection" href="#journey/${j.id}"><div class="collection-cover cover-${i}"><img src="/${['cover-discovery.jpg','cover-community.jpg','cover-workflow.jpg','cover-community.jpg'][i]}" alt="" loading="lazy" width="600" height="400"></div><div class="collection-body"><span class="overline">${j.topic}</span><h2>${j.title}</h2><p>${j.intro}</p><div>3 个步骤 · ${j.effort} ${icon('chevron-right')}</div></div></a>`).join('')}</div><p class="route-disclaimer">时间是任务拆解的参考估计。路线内示例用于学习流程，不代表已验证的增长效果。</p></div>`}

function detailTabs(r){return [['guide','book','使用指南',null],['reports','check-circle','实践记录',state.detail?.reports?.length||0],['discussions','issue-opened','讨论',state.detail?.discussions?.length||0],['proposals','git-branch','改进建议',state.detail?.proposals?.length||0],['history','graph','版本记录',state.detail?.revisions?.length||1]].map(([t,i,n,count])=>`<a href="${href(r.id)}?tab=${t}" ${state.tab===t?'aria-current="page"':''}>${icon(i)}${n}${count!==null?`<span class="counter">${count}</span>`:''}</a>`).join('')}
function renderRepo(){if(state.error){$('#main').innerHTML=empty('资源暂时无法打开',esc(state.error),'retry-detail','重新加载');return}const r=state.detail?.resource;if(!r){$('#main').innerHTML='<div class="loading-line" role="status">正在同步资源内容…</div>';return}const own=isOwn(r),summary=repo(r.id)||r;document.title=r.title+' · GrowthHub';$('#main').innerHTML=`<div class="repo-page"><div class="repo-header"><a class="back-link" href="${esc(lastListing)}">${icon('chevron-left')}返回资源库</a><div class="repo-title-row"><div class="repo-identity"><div class="repo-byline"><a href="#author/${encodeURIComponent(authorKey(r))}">${av(r.owner)}${esc(r.owner)}</a><span>${types[r.type]} · ${esc(r.topic)}</span><span class="badge">${r.sample?'示例资源':'社区资源'}</span></div><h1>${esc(r.title)}</h1><p class="repo-subtitle">${esc(r.desc)}</p></div><div class="repo-actions">${starButton(summary)}<button class="btn btn-sm" data-action="share">${icon('copy')}分享</button><button class="btn btn-sm" data-fork="${esc(r.id)}">${icon('repo-forked')}保存副本<span class="button-count">${summary.forks||0}</span></button></div></div>${r.forkedFrom?`<p class="fork-source">派生自 <a href="${href(r.forkedFrom)}">${esc(repo(r.forkedFrom)?.owner||'原作者')} / ${esc(repo(r.forkedFrom)?.name||'原始资源')}</a></p>`:''}${r.status&&r.status!=='published'?`<div class="notice">${r.status==='hidden'?'此资源已被管理员隐藏，请查看消息中的处理说明。':'此资源已下架，仅你和管理员可以查看。'}</div>`:''}<nav class="repo-nav" aria-label="资源导航">${detailTabs(r)}</nav></div><div class="repo-content"><section class="repo-primary">${state.error?`<div class="notice error">${esc(state.error)}<button data-action="retry-detail">重新加载</button></div>`:''}${state.loading?'<div class="loading-line">正在同步资源内容…</div>':''}${state.tab==='guide'?guideView(r,own):state.tab==='reports'?reportsView(r):state.tab==='discussions'?discussionView(r):state.tab==='proposals'?proposalView(r):historyView(r)}</section><aside class="repo-about">${practiceCallout(r)}<h2>关于</h2><p>${esc(r.desc)}</p>${tags(r)}<div class="about-facts"><span>${icon('book')}${types[r.type]}</span><span>${icon('check-circle')}${levels[r.difficulty]||'无需编程'}</span><span>${icon('star')}${summary.stars||0} 次收藏</span><span>${icon('repo-forked')}${summary.forks||0} 份副本</span><span>${icon('graph')}v${r.version} · ${date(r.updatedAt)}</span>${r.url?`<a target="_blank" rel="noopener" href="${esc(r.url)}">${icon('link-external')}项目原站</a>`:''}</div><section><h3>维护者</h3><a class="contributor" href="#author/${encodeURIComponent(authorKey(r))}">${av(r.owner)}<div><strong>${esc(r.owner)}</strong><span>${r.sample?'示例作者':'资源作者'}</span></div></a></section><section><h3>一起完善这个方法</h3><p>发现遗漏或有更好的做法？写下具体改进，让后来的人少走弯路。</p><button class="btn full" data-action="propose">${icon('git-branch')}提出改进</button></section><section class="resource-management">${own&&r.status!=='hidden'?`<button class="btn full" data-resource-status="${r.status==='archived'?'published':'archived'}">${r.status==='archived'?'重新发布资源':'下架资源'}</button>`:''}<button class="text-link" data-action="report">举报此资源</button></section><p class="rail-note">${r.sample?'此内容为示例，未经过真实业务验证。':'内容由作者分享，请结合自己的业务条件验证。'}<br>资源访问范围遵循社区权限。</p></aside></div></div>`}
function guideView(r,own){return `<div class="resource-toolbar"><span class="version-pill">${icon('git-branch')}v${r.version}<span>当前版本</span></span><div>${own?'<button class="btn" data-action="edit">'+icon('file-code')+'编辑资源</button>':''}<button class="btn primary" data-practice="${r.id}">${icon('check-circle')}${state.practices.some(p=>p.resource_id===r.id)?'继续实践':'开始实践'}</button><button class="btn" data-action="download">${icon('download')}下载指南</button></div></div>${practiceInline(r)}<div class="file-browser"><div class="last-change">${av(r.owner)}<strong>${esc(r.owner)}</strong><span>${esc(state.detail?.revisions?.[0]?.message||'发布示例使用指南')}</span><time>${date(r.updatedAt)}</time></div>${[['readme','使用指南.md','适用场景与完整执行步骤'],['checklist','实践检查清单.md','把方法变成一次可验证的实验']].map(([f,n,d])=>`<button class="file-item" data-doc="${f}">${icon('file')}<strong>${n}</strong><span>${d}</span>${icon('chevron-right')}</button>`).join('')}</div><article class="readme-panel"><div class="readme-top">${icon('book')}使用指南<span></span><button class="icon-btn" data-action="download" aria-label="下载使用指南">${icon('download')}</button>${own?`<button class="icon-btn" data-action="edit" aria-label="编辑使用指南">${icon('file-code')}</button>`:''}</div><div class="readme-content"><h2 class="guide-title">把方法用在你的业务里</h2><div class="guide-facts"><div><span>适合谁</span><strong>${esc(r.audience||'对该话题感兴趣的增长实践者')}</strong></div><div><span>使用门槛</span><strong>${levels[r.difficulty]||'无需编程'}</strong></div></div>${evidencePanel(r)}<div class="markdown">${markdown(r.readme.replace(/^# [^\n]+\n/,''))}</div></div></article>`}
function discussionView(r){const a=state.detail?.discussions||[];return `<div class="section-heading"><div><h2>讨论</h2><p>提出问题，分享实践结果，记录还没有答案的发现。</p></div><button class="btn primary" data-action="new-discussion">${icon('plus')}发起讨论</button></div><div class="issue-list"><div class="issue-list-head">${icon('issue-opened')}${a.filter(d=>d.status==='open').length} 个进行中<span>${a.filter(d=>d.status==='closed').length} 个已解决</span></div>${a.length?a.map(d=>`<details class="issue-item" ${state.openDiscussion===d.id?'open':''}><summary>${icon(d.status==='open'?'issue-opened':'check-circle')}<div><strong>${esc(d.title)}</strong><span>${esc(d.author_name)} · ${date(d.created_at)} · ${d.status==='open'?'进行中':'已解决'}</span></div>${icon('chevron-down')}</summary><div class="issue-body"><div class="markdown">${markdown(d.body)}</div>${(d.replies||[]).map(reply=>`<div class="discussion-reply"><div>${av(reply.author_name)}<strong>${esc(reply.author_name)}</strong><time>${date(reply.created_at)}</time></div><p>${esc(reply.body).replace(/\n/g,'<br>')}</p></div>`).join('')}<form class="reply-form" data-discussion-id="${d.id}"><label for="reply-${d.id}">添加回复</label><textarea id="reply-${d.id}" name="body" maxlength="5000" required placeholder="分享你的方法或补充背景…"></textarea><p class="form-error" role="alert"></p><button class="btn primary btn-sm" type="submit">发表回复</button></form>${d.author_id===state.user?.id||isOwn(r)?`<button class="btn" data-discussion="${d.id}" data-status="${d.status==='open'?'closed':'open'}">${d.status==='open'?'标记为已解决':'重新打开讨论'}</button>`:''}</div></details>`).join(''):empty('从一个具体问题开始','还没有讨论。可以先写下使用场景或实验中遇到的阻碍。','new-discussion','发起第一条讨论')}</div>`}
function proposalView(r){const a=state.detail?.proposals||[];return `<div class="section-heading"><div><h2>改进建议</h2><p>先说明为什么改，再对比内容。由作者决定是否采纳。</p></div><button class="btn primary" data-action="propose">提出改进</button></div>${a.length?a.map(p=>`<details class="proposal-item"><summary><span class="status-label ${p.status}">${icon(p.status==='merged'?'check':'git-branch')}${{open:'待审查',merged:'已采纳',closed:'已关闭'}[p.status]}</span><div><strong>${esc(p.title)}</strong><span>${esc(p.author_name)} · 基于 v${p.base_version} · ${date(p.created_at)}</span></div>${icon('chevron-down')}</summary><div class="issue-body"><p>${esc(p.body)}</p><div class="diff-heading"><strong>文档变更</strong><span>原内容 → 建议内容</span></div>${diffView(state.detail?.revisions.find(v=>v.version===p.base_version)?.data.readme||r.readme,p.data.readme)}${p.status==='open'?`<div class="review-actions">${isOwn(r)?`<button class="btn primary" data-proposal="${p.id}" data-decision="merge">${icon('check')}采纳并发布新版本</button>`:'<span class="muted">等待资源作者审查</span>'}${isOwn(r)||p.author_id===state.user?.id?`<button class="btn" data-proposal="${p.id}" data-decision="close">关闭建议</button>`:''}</div>`:''}</div></details>`).join(''):empty('让经验在协作中进化','补充遗漏的步骤、适用条件或实践发现。原文在作者采纳前保持原样。','propose','提交第一条改进')}`}
function diffView(before,after){const a=String(before).split('\n'),b=String(after).split('\n');let start=0;while(start<Math.min(a.length,b.length)&&a[start]===b[start])start++;let endA=a.length-1,endB=b.length-1;while(endA>=start&&endB>=start&&a[endA]===b[endB]){endA--;endB--}if(start===a.length&&start===b.length)return '<div class="notice">文档内容没有变化。</div>';return `<div class="diff-block" aria-label="内容差异">${a.slice(Math.max(0,start-2),start).map(l=>`<div><i> </i>${esc(l)||' '}</div>`).join('')}${a.slice(start,endA+1).map(l=>`<div class="removed"><i>−</i>${esc(l)||' '}</div>`).join('')}${b.slice(start,endB+1).map(l=>`<div class="added"><i>+</i>${esc(l)||' '}</div>`).join('')}${a.slice(endA+1,endA+3).map(l=>`<div><i> </i>${esc(l)||' '}</div>`).join('')}</div>`}
function historyView(r){const a=state.detail?.revisions||[];return `<div class="section-heading"><div><h2>版本记录</h2><p>每次修改都留下记录，随时查看当时的完整内容。</p></div><span class="badge">当前 v${r.version}</span></div><div class="timeline">${a.length?a.map(v=>`<article class="timeline-item"><span class="timeline-dot">${icon('git-branch')}</span><div><div class="timeline-title"><strong>${esc(v.message)}</strong><span class="badge">v${v.version}</span></div><p>${esc(v.author_name)} 更新于 ${new Date(v.created_at).toLocaleString('zh-CN')}</p><button class="btn btn-sm" data-version="${v.id}">查看此版本</button></div></article>`).join(''):`<article class="timeline-item"><span class="timeline-dot">${icon('git-branch')}</span><div><strong>示例资源 v1</strong><p>这份资源用于展示使用与协作流程。</p></div></article>`}</div>`}
let restoreFocus=null;
function openModal(title,body,footer=''){const m=$('#modal');if(!m.open)restoreFocus=document.activeElement;m.className=title==='导航'?'nav-dialog':'';m.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('x')}</button></div>${body}${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!m.open)m.showModal();m.scrollTop=0;document.body.classList.add('modal-open')}
function closeModal(){saveDraft();$('#modal').close();document.body.classList.remove('modal-open');restoreFocus?.isConnected&&restoreFocus.focus();editor=null}
function draftKey(){return 'growthhub-draft-v4-'+state.user?.id+'-'+(editor?.draftId||editor?.mode+'-'+(editor?.id||'new'))}
function saveDraft(){if(!editor)return;const f=$('#resource-form');if(f){for(const [k,v] of new FormData(f))editor[k]=String(v)}try{localStorage.setItem(draftKey(),JSON.stringify(editor));const s=$('#draft-status');if(s)s.textContent='草稿已保存在此设备'}catch{const s=$('#draft-status');if(s)s.textContent='无法保存草稿，请保持页面打开'}}
function publish(mode='new'){if(!community.gate())return;const r=state.detail?.resource||repo(state.id);editor={mode,requestId:crypto.randomUUID(),id:mode==='new'?null:r?.id,name:mode==='new'?'':r.name,title:mode==='new'?'':r.title,desc:mode==='new'?'':r.desc,readme:mode==='new'?'':r.readme,type:r&&mode!=='new'?r.type:'skill',topic:r&&mode!=='new'?r.topic:'GEO',audience:r&&mode!=='new'?r.audience||'':'',difficulty:r&&mode!=='new'?r.difficulty:'beginner',url:r&&mode!=='new'?r.url||'':'',disclosure:mode==='new'?'unspecified':r?.disclosure||'unspecified',evidenceStatus:mode==='new'?'untested':r?.evidenceStatus||'untested',evidence:mode==='new'?'':r?.evidence||'',limits:mode==='new'?'':r?.limits||'',effort:mode==='new'?'':r?.effort||'',version:mode==='new'?undefined:r?.version,changeTitle:'',message:''};try{const d=JSON.parse(localStorage.getItem(draftKey())||'null');if(d&&d.version===editor.version){editor={...editor,...d};toast('已恢复未完成的草稿')}}catch{}editorStep='write';renderEditor()}
function renderEditor(){const e=editor,proposal=e.mode==='proposal';if(editorStep==='preview'){openModal(proposal?'检查你的改进建议':'预览资源',`<div class="editor-steps"><span>1 填写内容</span><strong>2 检查并提交</strong></div><div class="dialog-body preview-document">${proposal?`<h3>${esc(e.changeTitle)}</h3><p>${esc(e.message)}</p>${diffView((state.detail?.resource||repo(state.id)).readme,e.readme)}`:`<span class="badge">${types[e.type]} · ${esc(e.topic)}</span><h2>${esc(e.title)}</h2><p>${esc(e.desc)}</p>${evidencePanel(e)}<div class="markdown">${markdown(e.readme)}</div>`}<p class="form-error" role="alert" id="editor-error"></p></div>`,`<button class="btn" data-action="editor-back">返回编辑</button><span class="muted">发布后可被访客浏览</span><button class="btn primary" data-action="editor-submit">${proposal?'提交改进建议':e.mode==='edit'?'保存新版本':'发布资源'}</button>`);return}
openModal(proposal?'提出改进建议':e.mode==='edit'?'编辑资源':'发布增长资源',`<div class="editor-steps"><strong>1 填写内容</strong><span>2 检查并提交</span></div><form id="resource-form" novalidate><div class="dialog-body">${proposal?`<div class="notice">${icon('git-branch')}基于 v${e.version} 提出修改，由资源作者审查后采纳。</div><div class="field"><label for="change-title">你想改进什么？ <span>*</span></label><input id="change-title" name="changeTitle" value="${esc(e.changeTitle)}" maxlength="100" placeholder="例如：补充内容更新后的复测步骤"></div><div class="field"><label for="change-message">为什么这样改？ <span>*</span></label><textarea id="change-message" name="message" maxlength="3000" placeholder="说明改动依据、适用条件或你的实践发现。">${esc(e.message)}</textarea></div>`:`<div class="field"><label>资源类型</label><div class="type-options">${Object.entries(types).map(([k,n])=>`<button type="button" data-editor-type="${k}" aria-pressed="${e.type===k}">${icon(k==='skill'?'book':k==='tool'?'tools':'comment-discussion')}<strong>${n}</strong></button>`).join('')}</div></div><div class="field"><label for="resource-title">资源标题 <span>*</span></label><input id="resource-title" name="title" maxlength="80" value="${esc(e.title)}" placeholder="用一句话说清楚，它能解决什么问题"><small>具体的任务比宽泛的概念更容易被发现。</small></div><div class="field"><label for="resource-desc">简单介绍 <span>*</span></label><textarea id="resource-desc" name="desc" maxlength="300" placeholder="背景、主要方法，以及适用场景。">${esc(e.desc)}</textarea></div><div class="form-grid"><div class="field"><label for="resource-topic">所属话题</label><select id="resource-topic" name="topic">${topics.map(t=>`<option ${e.topic===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="resource-level">使用门槛</label><select id="resource-level" name="difficulty">${Object.entries(levels).map(([k,n])=>`<option value="${k}" ${e.difficulty===k?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="field"><label for="resource-audience">适合谁 <small>选填</small></label><input id="resource-audience" name="audience" maxlength="100" value="${esc(e.audience)}" placeholder="例如：负责内容增长的市场团队"></div>`}<div class="field"><div class="editor-label"><label for="resource-body">${proposal?'修改后的完整指南':'使用指南'} <span>*</span></label><button type="button" data-action="template">使用写作提纲</button></div><div class="write-toolbar"><span>${icon('file')}直接输入文字，也支持 Markdown</span><span id="word-count">${e.readme.length} 字</span></div><textarea id="resource-body" name="readme" class="body-editor" maxlength="150000" placeholder="从适用场景、准备事项和具体步骤开始…">${esc(e.readme)}</textarea></div>${!proposal?`${qualityFields(e)}<details class="import-options"><summary>已有文档或项目链接？</summary><div class="field"><label for="resource-file">导入文本文件</label><input id="resource-file" type="file" accept=".md,.txt"><small>最大 150 KB，导入后仍可编辑。</small></div><div class="field"><label for="resource-url">项目链接 <small>选填</small></label><input id="resource-url" name="url" value="${esc(e.url)}" type="url" placeholder="https://" maxlength="2000"></div></details>${e.mode==='edit'?`<div class="field"><label for="change-message">更新说明</label><input id="change-message" name="message" value="${esc(e.message)}" placeholder="这次补充或修正了什么？" maxlength="120"></div>`:''}`:''}<p class="form-error" role="alert" id="editor-error"></p></div><div class="dialog-footer"><span class="muted" id="draft-status">本机自动保存 · 可同步到云端</span><button class="btn" type="button" data-action="save-cloud-draft">保存云端草稿</button><button class="btn primary" type="submit">预览${proposal?'改进':'内容'} ${icon('chevron-right')}</button></div></form>`)}
function validateEditor(){saveDraft();$('#field-error')?.remove();const e=editor;let error='',target='';for(const [key,label,id] of (e.mode==='proposal'?[['changeTitle','改进标题','change-title'],['message','改进说明','change-message'],['readme','修改后的指南','resource-body']]:[['title','资源标题','resource-title'],['desc','简单介绍','resource-desc'],['readme','使用指南','resource-body']])){if(!e[key].trim()){error='请填写'+label;target=id;break}}if(!error&&e.mode!=='proposal'&&e.evidenceStatus!=='untested'&&!e.evidence.trim()){error='请说明观察周期、样本和结果，或选择尚未验证';target='resource-evidence'}if(!error&&e.url){try{const u=new URL(e.url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error()}catch{error='请填写完整的 http 或 https 链接';target='resource-url'}}if(!error&&e.mode==='proposal'&&e.readme===(state.detail?.resource||repo(state.id)).readme){error='请先修改指南内容，再提交改进建议';target='resource-body'}if(error){$('#editor-error').textContent=error;$('#'+target)?.setAttribute('aria-invalid','true');const input=$('#'+target);if(input){input.setAttribute('aria-describedby','field-error');const hint=document.createElement('small');hint.id='field-error';hint.className='field-error';hint.textContent=error;input.after(hint);input.focus()}return false}return true}
async function commitEditor(button){
 if(!editor)return;button.disabled=true;button.textContent='正在保存…';const e={...editor};let result;
 try{if(e.mode==='proposal')result=await api('resources/'+e.id+'/proposals','POST',{title:e.changeTitle,body:e.message,data:{readme:e.readme},baseVersion:e.version});else result=await api(e.mode==='edit'?'resources/'+e.id:'resources',e.mode==='edit'?'PUT':'POST',e)}
 catch(error){$('#editor-error').textContent=error.message;button.disabled=false;button.textContent='重试保存';return}
 try{localStorage.removeItem(draftKey());if(e.draftId)await api('drafts/'+e.draftId,'DELETE',{})}catch{}editor=null;closeModal();
 const target=href(e.mode==='proposal'?e.id:result.id)+(e.mode==='proposal'?'?tab=proposals':'');
 try{await refresh();go(target);toast(e.mode==='proposal'?'改进建议已提交，原文保持不变':e.mode==='edit'?'新版本已保存':'资源已发布到社区')}
 catch{go(target);toast('内容已保存。列表暂时未刷新，可重新连接后查看。')}
}
async function fork(id,button){button.disabled=true;try{const r=state.detail?.resource?.id===id?state.detail.resource:(await api('resources/'+id)).resource;const result=await api('resources','POST',{...r,requestId:button.dataset.requestId||(button.dataset.requestId=crypto.randomUUID()),forkedFrom:id});await refresh();go(href(result.id));toast('副本已保存，可开始编辑你的实践')}catch(e){toast(e.message);button.disabled=false}}
function discussionModal(){openModal('发起讨论',`<form id="discussion-form"><div class="dialog-body"><div class="field"><label for="discussion-title">讨论标题</label><input id="discussion-title" name="title" maxlength="100" required placeholder="一个具体的问题或发现"></div><div class="field"><label for="discussion-body">背景与内容</label><textarea id="discussion-body" class="body-editor" name="body" maxlength="5000" required placeholder="描述你的场景、已经尝试的方法和需要帮助的地方。"></textarea></div><p class="form-error" id="discussion-error" role="alert"></p></div><div class="dialog-footer"><span class="muted">对方法认真，对人友善。</span><button class="btn primary" type="submit">发表讨论</button></div></form>`)}
function guide(){openModal('在 GrowthHub，经验可以继续生长',`<div class="dialog-body"><div class="guide-step"><span>1</span><div><h3>发现一个方法</h3><p>按话题和使用门槛筛选，先读清适用条件与步骤。</p></div></div><div class="guide-step"><span>2</span><div><h3>开始一次小实验</h3><p>记录场景、基线与观察周期。计划默认仅自己可见，在“我的实践”继续。</p></div></div><div class="guide-step"><span>3</span><div><h3>记录结果，也记录失败</h3><p>完成复盘后，可以主动分享到资源页。没有改善和结果不明确同样有价值；文档改进仍由作者审查。</p></div></div><div class="notice">资源、收藏、讨论和版本记录保存在社区中。草稿可保存到云端，并在“我的账户 → 云端草稿”继续编辑。</div></div>`,`<button class="btn" data-action="close">开始探索</button><button class="btn primary" data-action="publish">发布第一个资源</button>`)}
function download(name,body,type='text/markdown;charset=utf-8'){const u=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function checklist(r){return '# '+r.title+' · 实践检查清单\n\n- 确认目标用户与适用场景\n- 记录当前基线\n- 写清本次实验假设\n- 确定步骤、负责人和时间\n- 记录结果、局限与下一步\n- 保留原作者与引用来源\n\n来源：'+location.href}
async function share(){try{await navigator.clipboard.writeText(location.href);toast('链接已复制，公开资源无需登录即可查看')}catch{openModal('分享资源',`<div class="dialog-body"><p>公开资源可以直接查看；已下架的资源仅作者和管理员可见。</p><input class="share-input" aria-label="资源链接" readonly value="${esc(location.href)}"></div>`)}}
async function start(){try{await refresh();await route()}catch(e){$('#app').innerHTML=`<div class="boot"><span class="brand-mark"><i></i><i></i><i></i></span><h1>GrowthHub</h1><p>${esc(e.message)}</p><button class="btn primary" data-action="retry">重新连接</button>${e.status===401?'<a class="btn" href="/signin-with-chatgpt?return_to=%2F" target="_top">登录后继续</a>':''}</div>`}}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button,a');if(!b)return;if(b.tagName==='A'&&b.getAttribute('href')?.startsWith('#')&&!ev.metaKey&&!ev.ctrlKey){if(b.getAttribute('href')==='#main'){$('#main').focus();return}ev.preventDefault();go(b.getAttribute('href'));return}const a=b.dataset.action;
 try{if(await community.click(b))return}catch(e){const out=$('#modal .form-error');if(out)out.textContent=e.message;else toast(e.message);return}
 if(a==='inbox'){go('#inbox');return}
 if(a==='download-draft'){saveDraft();download('GrowthHub-草稿备份.json',JSON.stringify(editor,null,2),'application/json');return}
 if(a==='save-cloud-draft'){await saveCloudDraft(b);return}
 if((['publish','edit','propose','new-discussion','edit-profile'].includes(a)||b.dataset.star||b.dataset.fork||b.dataset.practice||b.dataset.discussion||b.dataset.proposal)&&!community.gate())return;
 if(a==='close')closeModal();if(a==='menu')openModal('导航',`<div class="dialog-body mobile-menu-links">${[['explore','发现 Skills'],['trending','实践排行榜'],['collections','入门路线'],['practice','我的实践'],['stars','我的收藏'],['profile','我的资源']].map(([p,n])=>`<a href="#${p}">${n}${icon('chevron-right')}</a>`).join('')}<h3>增长话题</h3>${topics.map(t=>`<button data-topic="${esc(t)}" aria-pressed="${state.topic===t}">${esc(t)}${icon('chevron-right')}</button>`).join('')}</div>`);if(b.dataset.practice)practiceModal(b.dataset.practice,b.dataset.complete==='true');if(a==='profile')go('#profile');if(a==='retry')start();if(a==='retry-detail')loadDetail();if(a==='publish')publish();if(a==='edit')publish('edit');if(a==='propose')publish('proposal');if(a==='guide')guide();if(a==='routes')go('#collections');if(a==='reset')go('#explore');if(a==='clear-filters'){state.q='';state.topic='all';state.level='all';state.type='all';$('#search').value='';updateQuery()}if(a==='share')share();
 if(b.dataset.sort){state.sort=b.dataset.sort;updateQuery()}if(b.dataset.filterType){state.type=b.dataset.filterType;updateQuery()}if(b.dataset.topic){toggleTopic(b.dataset.topic)}
 if(b.dataset.star){b.disabled=true;const id=b.dataset.star;try{await api('resources/'+id+'/star','PUT',{active:!state.stars.includes(id)});await refresh();renderMain();toast(state.stars.includes(id)?'已加入收藏':'已取消收藏')}catch(e){toast(e.message);b.disabled=false}}
 if(b.dataset.fork)fork(b.dataset.fork,b);if(a==='download'){const r=state.detail?.resource||repo(state.id);download(r.name+'.md',r.readme)}
 if(b.dataset.doc){const r=state.detail?.resource||repo(state.id);if(b.dataset.doc==='readme')$('.readme-panel')?.scrollIntoView({behavior:'smooth',block:'start'});else openModal('实践检查清单',`<div class="dialog-body markdown">${markdown(checklist(r))}</div>`,`<button class="btn" data-action="close">返回</button><button class="btn primary" data-action="download-checklist">下载清单</button>`)}if(a==='download-checklist')download('实践检查清单.md',checklist(state.detail?.resource||repo(state.id)));
 if(b.dataset.editorType){saveDraft();editor.type=b.dataset.editorType;renderEditor()}if(a==='template'){saveDraft();editor.readme+=(editor.readme?'\n\n':'')+'## 适用场景\n\n## 开始前的准备\n\n## 具体步骤\n\n- 第一步：\n- 第二步：\n- 第三步：\n\n## 结果与限制\n\n## 下一步\n';renderEditor();saveDraft();$('#resource-body').focus()}if(a==='editor-back'){editorStep='write';renderEditor()}if(a==='editor-submit')commitEditor(b);
 if(a==='new-discussion')discussionModal();if(b.dataset.discussion){b.disabled=true;try{await api('resources/'+state.id+'/discussions/'+b.dataset.discussion,'PATCH',{status:b.dataset.status});await loadDetail();toast('讨论状态已更新')}catch(e){toast(e.message);b.disabled=false}}
 if(b.dataset.proposal){b.disabled=true;try{await api('resources/'+state.id+'/proposals/'+b.dataset.proposal,'PATCH',{action:b.dataset.decision});await refresh();await loadDetail();toast(b.dataset.decision==='merge'?'改进已采纳，新版本已保存':'改进建议已关闭')}catch(e){toast(e.message);b.disabled=false}}
 if(b.dataset.version){const v=state.detail.revisions.find(v=>v.id===b.dataset.version);openModal('版本 v'+v.version+' · '+v.message,`<div class="dialog-body markdown">${markdown(v.data.readme)}</div>`,`<button class="btn" data-action="close">返回版本记录</button>`)}
 if(a==='edit-profile')openModal('编辑个人资料',`<form id="profile-form"><div class="dialog-body"><div class="field"><label for="profile-name">显示名称</label><input id="profile-name" name="name" value="${esc(state.user.name)}" maxlength="50" required></div><div class="field"><label for="profile-bio">个人介绍</label><textarea id="profile-bio" name="bio" maxlength="200">${esc(state.user.bio||'')}</textarea></div><p class="form-error" id="profile-error" role="alert"></p></div><div class="dialog-footer"><span></span><button class="btn primary" type="submit">保存资料</button></div></form>`);
 if(a==='export-legacy')download('GrowthHub-旧版资源备份.json',localStorage.getItem('growthhub-v1'),'application/json');
 if(a==='about')openModal('关于 GrowthHub',`<div class="dialog-body markdown"><h2>让增长经验可以被复用与改进。</h2><p>分享具体的场景、方法、结果与限制。资源保留作者与派生关系，改进在作者审查后生成新版本。</p><h3>社区约定</h3><ul><li>标注来源，尊重原创与授权。</li><li>不上传客户隐私、账号凭据或未经许可的数据。</li><li>区分事实、假设和示例，说明结论适用边界。</li></ul><div class="notice">当前为邀请试用版。可公开浏览资源；受邀成员可参与贡献。可通过资源页举报不当内容，处理结果会出现在消息通知中。</div></div>`,`<button class="btn primary" data-action="close">了解了</button>`);
});
const outcomes={pending:'尚未得出结论',untested:'尚未验证',improved:'观察到改善','no-improvement':'未达预期',mixed:'结果不明确'};
function goalPicker(){return `<section class="goal-picker" aria-label="按目标开始"><div class="goal-heading"><strong>从你的问题开始</strong><a href="#collections" aria-label="查看全部入门路线">${icon('chevron-right')}</a></div><div class="goal-links">${journeys.map((j,i)=>`<a href="#journey/${j.id}"><span class="goal-number">0${i+1}</span><span>${j.title}</span>${icon('chevron-right')}</a>`).join('')}</div><p>不需要懂代码，选一条路线就能开始。</p></section>`}
function renderJourney(){const j=journeys.find(j=>j.id===state.id);if(!j){$('#main').innerHTML=empty('路线不存在','回到资源库选择一个增长问题。');return}document.title=j.title+' · GrowthHub';$('#main').innerHTML=`<div class="journey-page"><a class="back-link" href="#collections">${icon('chevron-left')}所有入门路线</a><div class="journey-header"><span class="overline">${esc(j.topic)} · 三步实践路线</span><h1>${j.title}</h1><p>${j.intro}</p><span class="badge">${j.effort} · 参考估计</span></div><div class="journey-layout"><section><div class="first-task"><span class="task-number">01</span><div><h2>今天先完成这一件事</h2><p>${j.first}</p><a class="btn primary" href="${href(j.steps[0][0])}">打开第一步 ${icon('chevron-right')}</a></div></div><div class="journey-steps">${j.steps.map(([rid,title,task],i)=>{const r=repo(rid),p=state.practices.find(p=>p.resource_id===rid);return `<article><span class="step-circle">${i+1}</span><div><div class="step-title"><h2>${title}</h2>${p?`<span class="badge">${p.stage==='complete'?'已复盘':'实践中'}</span>`:''}</div><p>${task}</p>${rid==='experiment-tracker'?`<a href="#practice">在“我的实践”记录结果 ${icon('chevron-right')}</a>`:`<a href="${href(rid)}">${esc(r?.title||title)} ${icon('chevron-right')}</a>`}</div></article>`}).join('')}</div></section><aside class="journey-aside"><h2>怎样算完成？</h2><ul><li>记录开始前的状态。</li><li>只改变一个主要因素。</li><li>保留周期、样本与原始观察。</li><li>写清结果和不确定性。</li></ul><div class="notice">没有改善也是结果。不需要把每次实验包装成成功案例。</div><a href="#practice">回到我的实践 ${icon('chevron-right')}</a><p class="rail-note">路线提供的是行动顺序。示例资源未经过业务验证，请结合自己的条件使用。</p></aside></div></div>`}
function evidencePanel(r){return `<section class="evidence-panel"><div><strong>${icon('info')} 使用前先看</strong><span class="badge">${r.sample?'示例 · 未经业务验证':'作者自述 · '+(outcomes[r.evidenceStatus]||'尚未验证')}</span></div><dl><dt>时间与成本</dt><dd>${esc(r.effort||'作者尚未说明，请先做小范围测试。')}</dd><dt>结果依据</dt><dd>${esc(r.evidence||'尚未提供观察周期、样本与结果。收藏数不代表有效性。')}</dd><dt>适用边界</dt><dd>${esc(r.limits||'尚未补充。使用前请确认行业、渠道与资源条件。')}</dd><dt>利益关系</dt><dd>${r.sample?'示例内容':({'unspecified':'作者尚未说明','independent':'作者声明无商业关联','creator':'作者是项目 / 工具的参与者','sponsored':'作者声明包含赞助或推广关系'}[r.disclosure||'unspecified'])}</dd></dl><p>实践者的观察不代表因果证明，也不保证适用于你的业务。</p></section>`}
function qualityFields(e){return `<section class="quality-fields"><h3>让别人判断：这个方法适不适合我？</h3><p>如实填写观察与边界。尚未验证、失败或结果不明确，都可以分享。</p><div class="form-grid"><div class="field"><label for="resource-evidence-status">你实践过吗？</label><select id="resource-evidence-status" name="evidenceStatus">${['untested','improved','no-improvement','mixed'].map(v=>`<option value="${v}" ${e.evidenceStatus===v?'selected':''}>${outcomes[v]}</option>`).join('')}</select></div><div class="field"><label for="resource-effort">时间与成本 <small>选填</small></label><input id="resource-effort" name="effort" value="${esc(e.effort)}" maxlength="100" placeholder="例如：2 人，每周 3 小时，无额外预算"></div></div><div class="field"><label for="resource-evidence">结果依据</label><textarea id="resource-evidence" name="evidence" maxlength="1500" placeholder="做了多久、样本多少、前后发生什么变化？未验证可以留空。">${esc(e.evidence)}</textarea><small>选择已实践的结论时必填；请勿只写百分比而省略基线。</small></div><div class="field"><label for="resource-limits">不适用的场景 / 失败经验 <small>选填</small></label><textarea id="resource-limits" name="limits" maxlength="1000" placeholder="哪些条件下没用？有什么干扰因素或尚未确认的假设？">${esc(e.limits)}</textarea></div><div class="field"><label for="resource-disclosure">你与提到的项目是什么关系？</label><select id="resource-disclosure" name="disclosure">${Object.entries({unspecified:'暂未说明',independent:'无商业关联',creator:'我是项目 / 工具的参与者',sponsored:'包含赞助或推广关系'}).map(([v,t])=>`<option value="${v}" ${e.disclosure===v?'selected':''}>${t}</option>`).join('')}</select></div><p class="quality-reminder">在站内写清可执行步骤和与你的项目的关系。只有外链、广告语或无法解释的增长数字，不能帮助别人复用。</p></section>`}
function practiceInline(r){const p=state.practices.find(p=>p.resource_id===r.id);return p?`<div class="practice-inline"><span>${icon('check-circle')}${p.stage==='complete'?'这次实践已复盘':'你正在实践这个方法'} · ${p.visibility==='community'?'已分享':'仅自己可见'}</span><div><button data-practice="${r.id}" data-complete="true">${p.stage==='complete'?'查看复盘':'记录结果'}</button><a href="#practice">我的实践 ${icon('chevron-right')}</a></div></div>`:''}
function practiceCallout(r){const p=state.practices.find(p=>p.resource_id===r.id);return `<section class="practice-callout"><span class="overline">把方法用起来</span><h3>${p?p.stage==='complete'?'回来看这次实践':'继续你的实践':'从一次小实验开始'}</h3><p>${p?'基于 v'+p.resource_version+' · '+(p.visibility==='community'?'已分享到社区':'仅自己可见'):'先记录场景与基线，再比较实际结果。计划默认仅自己可见。'}</p><button class="btn primary full" data-practice="${esc(r.id)}" ${p?.stage==='complete'?'data-complete="true"':''}>${icon('check-circle')}${p?'打开实践记录':'开始实践'}</button>${p?.stage==='running'?`<button class="btn full" data-practice="${esc(r.id)}" data-complete="true">记录结果</button>`:''}</section>`}
function renderPractices(){const running=state.practices.filter(p=>p.stage==='running'),done=state.practices.filter(p=>p.stage==='complete');$('#main').innerHTML=`<div class="practices-page"><div class="page-heading"><div><h1>我的实践</h1><p>把读过的方法，变成一次有起点、有结果的尝试。</p></div><a class="btn" href="#collections">选择入门路线</a></div><div class="practice-summary"><span>${icon('graph')}<strong>${running.length}</strong> 项正在实践</span><span>${icon('check-circle')}<strong>${done.length}</strong> 项已复盘</span><span>${icon('shield-check')}计划默认仅自己可见</span></div>${state.practices.length?[['正在实践',running],['已经复盘',done]].map(([title,items])=>items.length?`<section class="practice-group"><h2>${title}</h2>${items.map(p=>{const r=repo(p.resource_id);return `<article class="practice-row"><div><span class="overline">基于 v${p.resource_version} · ${p.visibility==='community'?'已分享':'仅自己可见'}</span><h3><a href="${href(p.resource_id)}">${esc(r?.title||'原资源')}</a></h3><p>${esc(p.data.metric)} · ${p.stage==='complete'?esc(outcomes[p.data.outcome]):'基线：'+esc(p.data.baseline)}</p><span class="muted">观察周期：${esc(p.data.timeframe)}</span>${p.data.nextStep?`<p class="next-step">下一步：${esc(p.data.nextStep)}</p>`:''}</div><div class="practice-row-actions"><button class="btn" data-practice="${p.resource_id}" ${p.stage==='complete'?'data-complete="true"':''}>${p.stage==='complete'?'查看 / 编辑复盘':'编辑计划'}</button>${p.stage==='running'?`<button class="btn primary" data-practice="${p.resource_id}" data-complete="true">记录结果</button>`:''}</div></article>`}).join('')}</section>`:'').join(''):empty('从一次小实验开始','打开一个方法，点击“开始实践”。不用等准备完美，也不用承诺一定成功。','routes','选择一个增长问题')}<p class="route-disclaimer">只有你主动勾选“分享到社区”的完整复盘，才会出现在资源的实践记录中。</p></div>`}
function reportsView(r){const a=state.detail?.reports||[];return `<div class="section-heading"><div><h2>实践记录</h2><p>同一个方法，在不同条件下可能有不同结果。</p></div><button class="btn primary" data-practice="${r.id}">记录我的实践</button></div><div class="notice">全部为实践者自述。保留未达预期和不明确的结果，不用收藏数代替验证。</div>${a.length?a.map(p=>`<article class="report-card"><div class="report-heading">${av(p.author_name)}<strong>${esc(p.author_name)}</strong><span class="outcome ${p.data.outcome}">${outcomes[p.data.outcome]}</span></div><p class="muted">基于资源 v${p.resource_version} · ${date(p.updated_at)}</p><dl><dt>场景</dt><dd>${esc(p.data.context)}</dd><dt>指标与基线</dt><dd>${esc(p.data.metric)} · ${esc(p.data.baseline)}</dd><dt>周期 / 样本</dt><dd>${esc(p.data.timeframe)}</dd><dt>实际结果</dt><dd>${esc(p.data.result)}</dd><dt>局限与干扰</dt><dd>${esc(p.data.limits)}</dd>${p.data.nextStep?`<dt>下一步</dt><dd>${esc(p.data.nextStep)}</dd>`:''}</dl></article>`).join(''):`<div class="empty-state">${icon('graph')}<h2>还没有人分享实践结果</h2><p>先记录自己的基线和计划。复盘后再决定是否分享，无需编造成功数据。</p></div>`}`}
function practiceModal(rid,complete=false){const r=repo(rid),p=state.practices.find(p=>p.resource_id===rid);if(!r)return;complete=complete||p?.stage==='complete';const d=p?.data||{};const field=(key,label,placeholder,max=1000,area=false,required=true)=>`<div class="field"><label for="practice-${key}">${label}${required?' <span>*</span>':' <small>选填</small>'}</label>${area?`<textarea id="practice-${key}" name="${key}" maxlength="${max}" placeholder="${placeholder}" ${required?'required':''}>${esc(d[key]||'')}</textarea>`:`<input id="practice-${key}" name="${key}" maxlength="${max}" placeholder="${placeholder}" value="${esc(d[key]||'')}" ${required?'required':''}>`}</div>`;openModal(complete?'记录这次实践的结果':'开始一次实践',`<form id="practice-form" data-resource-id="${rid}" data-version="${p?.version||0}" data-stage="${complete?'complete':'running'}"><div class="dialog-body"><div class="notice">${icon('book')} ${esc(r.title)} · 基于 v${p?.resource_version||r.version}</div>${field('context','用在什么场景','例如：两人内容团队，每周产出一篇文章',1000,true)}<div class="form-grid">${field('metric','观察什么指标','例如：每篇内容投入的小时数',120)}${field('baseline','开始前是什么情况','例如：每篇约 6 小时；若没有数据，写明待测量',200)}</div>${field('timeframe','观察周期 / 样本','例如：10 月 7–21 日，4 篇文章',100)}${complete?`<div class="field"><label for="practice-outcome">观察结论 <span>*</span></label><select id="practice-outcome" name="outcome" required><option value="">请选择，不需要都是成功</option>${['improved','no-improvement','mixed'].map(v=>`<option value="${v}" ${d.outcome===v?'selected':''}>${outcomes[v]}</option>`).join('')}</select></div>${field('result','实际发生了什么','记录具体结果；没有变化、变差或样本不足也可以。',1500,true)}${field('limits','有哪些局限或干扰','例如：样本只有 4 篇，选题难度不同，不能直接归因。',1000,true)}`:''}${field('nextStep','下一步准备做什么','一个具体行动，例如：下周用相近难度的选题再试一次',500,true,false)}${complete?`<label class="share-choice"><input type="checkbox" name="share" ${p?.visibility==='community'?'checked':''}><span><strong>把这份复盘分享到社区</strong><small>内容会出现在资源的实践记录中。未勾选时只有自己可见，请先去掉客户隐私等敏感信息。</small></span></label>`:'<p class="muted">计划保存到你的账户。你可以稍后回来补充结果，再决定是否分享。</p>'}<p class="form-error" role="alert"></p></div><div class="dialog-footer"><span class="muted">不以成功论贡献</span><button class="btn primary" type="submit">${complete?'保存复盘':'保存实践计划'}</button></div></form>`)}

let searchTimer;document.addEventListener('input',ev=>{if(ev.target.id==='search'){state.q=ev.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(!['explore','trending','stars','profile','author'].includes(state.route)){state.route='explore';state.id=null;state.type='all';state.sort='popular'}updateQuery()},120)}if(ev.target.closest('#resource-form')){ev.target.removeAttribute('aria-invalid');ev.target.removeAttribute('aria-describedby');$('#field-error')?.remove();$('#editor-error').textContent='';saveDraft();if($('#word-count'))$('#word-count').textContent=editor.readme.length+' 字'}});
document.addEventListener('change',async ev=>{if(ev.target.id==='sort-filter'){state.sort=ev.target.value;updateQuery()}if(ev.target.id==='level-filter'){state.level=ev.target.value;updateQuery()}if(ev.target.id==='discovery-type'){state.type=ev.target.value;updateQuery()}if(ev.target.id==='discovery-topic'){state.topic=ev.target.value;updateQuery()}if(ev.target.closest('#resource-form'))saveDraft();if(ev.target.id==='resource-file'){const f=ev.target.files[0];if(!f)return;if(f.size>150000||!(/\.(txt|md)$/i.test(f.name))){$('#editor-error').textContent='请选择不超过 150 KB 的 .txt 或 .md 文件';return}editor.readme=await f.text();$('#resource-body').value=editor.readme;saveDraft();toast('文档已导入，原草稿已更新')}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target;if(await community.submit(f))return;if(!community.gate())return;if(f.id==='resource-form'){if(validateEditor()){editorStep='preview';renderEditor()}return}const button=f.querySelector('[type=submit]');if(!button)return;button.disabled=true;try{const body=Object.fromEntries(new FormData(f));if(f.id==='practice-form'){const {stage,...data}=body;const rid=f.dataset.resourceId;await api('resources/'+rid+'/practice','PUT',{stage:f.dataset.stage,visibility:body.share==='on'?'community':'private',version:Number(f.dataset.version),data});closeModal();await refresh();if(state.route==='repo')await loadDetail();else renderMain();toast(body.share==='on'?'实践复盘已分享，失败经验同样有价值':'实践已保存，仅自己可见')}if(f.classList.contains('reply-form')){const id=f.dataset.discussionId;await api('resources/'+state.id+'/discussions/'+id+'/replies','POST',body);state.openDiscussion=id;await loadDetail();toast('回复已发表')}if(f.id==='discussion-form'){await api('resources/'+state.id+'/discussions','POST',body);closeModal();await loadDetail();toast('讨论已发表')}if(f.id==='profile-form'){await api('profile','PUT',body);closeModal();await refresh();shell();toast('资料已保存')}}catch(e){const out=f.querySelector('.form-error');if(out)out.textContent=e.message;button.disabled=false}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('nav-open');if((e.key==='/'&&!['INPUT','TEXTAREA'].includes(e.target.tagName))||((e.metaKey||e.ctrlKey)&&e.key==='k')){e.preventDefault();$('#search')?.focus()}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});window.addEventListener('hashchange',route);window.addEventListener('beforeunload',saveDraft);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_growth_resources',description:'搜索 GrowthHub 增长资源并在界面展示结果。',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(typeof input?.query!=='string'||input.query.length>100)throw Error('query must be a string of at most 100 characters');state.route='explore';state.q=input.query;state.type='all';state.topic='all';state.level='all';state.sort='popular';shell();updateQuery();return {results:filtered().map(r=>({id:r.id,title:r.title,type:r.type}))}}})).catch(()=>{})}catch{}}
async function saveCloudDraft(button){
 if(!editor)return;saveDraft();button.disabled=true;
 try{const previousKey=draftKey(),key=editor.draftId||crypto.randomUUID(),data={...editor,draftId:key};const result=await api('drafts/'+key,'PUT',{data,version:editor.cloudVersion||0});try{localStorage.removeItem(previousKey)}catch{}editor.draftId=key;editor.cloudVersion=result.version;saveDraft();$('#draft-status').textContent='云端已保存 · 仅自己可见';toast('草稿已保存，可在其他设备继续编辑')}
 catch(e){$('#editor-error').textContent=e.message;$('#editor-error').insertAdjacentHTML('beforeend',' <button type="button" class="btn btn-sm" data-action="download-draft">下载本机草稿</button>');toast('云端未保存，本机草稿仍在')}
 finally{button.disabled=false}
}
async function resumeDraft(d){
 if(!d)return;if(d.data.mode!=='new'){const detail=await api('resources/'+d.data.id);if(detail.resource.version!==d.data.version){openModal('原资源已有新版本',`<div class="dialog-body"><p>为了保留你的修改，请先下载这份草稿，再基于最新资源重新编辑。</p><button class="btn" data-action="close">返回草稿箱</button></div>`);download('GrowthHub-草稿.md',d.data.readme);return}state.detail=detail;state.id=d.data.id}
 editor={...d.data,draftId:d.id,cloudVersion:d.version};editorStep='write';renderEditor();
}
const community=createCommunity({state,esc,icon,av,api,go,toast,refresh,shell,openModal,closeModal,download,href,resumeDraft,loadDetail});
start();
